export type Tonality = 'calm' | 'reassuring' | 'empathic' | 'friendly' | 'confident' | 'excited' | 'neutral';
export type UserTone = 'confident' | 'calm' | 'enthusiastic' | 'neutral' | 'hesitant' | 'nervous' | 'defensive' | 'frustrated' | 'upset';
