     8	export function Avatar({
     9	  state,
    10	  gender = 'male',
    11	  scenario = 'interview',
    12	  difficulty = 'neutral',
    13	  volume: explicitVolume,
    14	}: {
    15	  state: AvatarState;
    16	  gender?: 'male' | 'female';
    17	  scenario?: string;
    18	  difficulty?: 'friendly' | 'neutral' | 'challenging';
    19	  volume?: number;
    20	}) {
    21	  const isFormal = scenario === 'interview' || scenario === 'raise';
    22	
    23	  // Dynamic voice modulation (大声变大模拟与自然声学起伏)
    24	  const [speechVol, setSpeechVol] = useState(0);
    25	
    26	  useEffect(() => {
    27	    if (explicitVolume !== undefined || state !== 'speaking') return;
    28	
    29	    let animId: number;
    30	    const startTime = performance.now();
    31	
    32	    function updateVolume(now: number) {
    33	      const t = (now - startTime) / 1000;
    34	      // Natural speech-like cadence: harmonic waves + periodic peaks
    35	      const base = Math.sin(t * 7.5) * 0.35 + Math.sin(t * 13.2) * 0.2 + 0.45;
    36	      const speechVolume = Math.max(0.1, Math.min(1.0, base));
    37	      setSpeechVol(speechVolume);
    38	      animId = requestAnimationFrame(updateVolume);
    39	    }
    40	
    41	    animId = requestAnimationFrame(updateVolume);
    42	    return () => cancelAnimationFrame(animId);
    43	  }, [state, explicitVolume]);
    44	
    45	  // Color & Hue mapping for emotions/difficulties:
    46	  // Neutral: Electric Azure / Cyan (#1FD5F9) - matches user reference
    47	  // Friendly: Vivid Emerald Lake (#10B981) - joyful / calm
    48	  // Challenging: Intense Crimson Flame (#F43F5E) - angry / aggressive pushback
    49	  const moodConfig = {
    50	    neutral: {
    51	      color: '#1FD5F9',
    52	      colorShift: 0.08,
    53	    },
    54	    friendly: {
    55	      color: '#10B981',
    56	      colorShift: 0.16,
    57	    },
