   140	function finalizeStreamingWav(source: Uint8Array) {
   141	    // Gradium streams WAV with unknown RIFF/data sizes. Finalize only these
   142	    // sentinel fields after the bounded response ends; validate everything next.
   143	    const bytes = source.slice();
