   145	        return bytes;
   146	    const view = new DataView(bytes.buffer);
   147	    const tag = (offset: number) => new TextDecoder().decode(bytes.subarray(offset, offset + 4));
   148	    if (tag(0) !== 'RIFF' || tag(8) !== 'WAVE')
   149	        return bytes;
   150	    if (view.getUint32(4, true) === 0xffffffff)
   151	        view.setUint32(4, bytes.length - 8, true);
