     1	import { z } from 'zod';
     2	import { speechMetadataSchema } from './speech-schema';
     3	import type { ConversationMessage, Difficulty, FeedbackReport, ScenarioId } from './contracts';
     4	import { ASSESSMENT_DIMENSIONS, reportSchema } from './feedback';
     5	
     6	export const PROFILE_STORAGE_KEY = 'rehearsal.profile.v1';
     7	export const MAX_PROFILE_SESSIONS = 50;
     8	const MAX_PROFILE_BYTES = 4 * 1024 * 1024;
     9	export const COACHING_METRICS = ASSESSMENT_DIMENSIONS.map(({ id, label }) => ({ key: id, label }));
    10	
    11	export type SavedSession = {
    12	    id: string;
    13	    completedAt: string;
    14	    scenarioId: ScenarioId;
    15	    difficulty: Difficulty;
    16	    customScenario?: string;
    17	    targetRole?: string;
    18	    durationSeconds: number;
    19	    messages: ConversationMessage[];
    20	    report: FeedbackReport;
    21	};
    22	export type LocalProfile = { version: 1; sessions: SavedSession[] };
    23	export type ProfileStorage = Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>;
    24	export class ProfileStorageError extends Error {
    25	    constructor(message: string) {
    26	        super(message);
    27	        this.name = 'ProfileStorageError';
    28	    }
    29	}
    30	
    31	const sessionSchema = z.object({
    32	    id: z.string().min(1).max(128),
    33	    completedAt: z.iso.datetime(),
    34	    scenarioId: z.enum(['interview', 'raise', 'relationship', 'feedback', 'flatmate', 'coldcall', 'bazaar', 'custom']),
    35	    difficulty: z.enum(['friendly', 'neutral', 'challenging']),
    36	    customScenario: z.string().max(1500).optional(),
    37	    targetRole: z.string().trim().max(200).optional(),
    38	    durationSeconds: z.number().finite().min(0).max(86400),
    39	    messages: z.array(z.object({
    40	        role: z.enum(['user', 'assistant']),
    41	        content: z.string().min(1).max(4000),
    42	        speech: speechMetadataSchema.optional()
    43	    }).strict()).min(1).max(40),
    44	    report: reportSchema
    45	}).strict().refine(session => session.scenarioId !== 'custom' || Boolean(session.customScenario?.trim()), {
    46	    message: 'A custom session needs its scenario description.'
    47	});
    48	const profileSchema = z.object({ version: z.literal(1), sessions: z.array(sessionSchema).max(MAX_PROFILE_SESSIONS) }).strict()
    49	    .refine(profile => new Set(profile.sessions.map(session => session.id)).size === profile.sessions.length, { message: 'Duplicate session IDs.' });
    50	const emptyProfile = (): LocalProfile => ({ version: 1, sessions: [] });
    51	
    52	function resolveStorage(storage?: ProfileStorage): ProfileStorage {
    53	    if (storage) return storage;
    54	    try {
    55	        if (typeof window !== 'undefined') return window.localStorage;
    56	    } catch { /* Report denied browser storage below. */ }
    57	    throw new ProfileStorageError('Local profile storage is unavailable in this browser.');
    58	}
    59	
    60	function withinSizeLimit(raw: string): boolean {
    61	    return raw.length <= MAX_PROFILE_BYTES && new TextEncoder().encode(raw).byteLength <= MAX_PROFILE_BYTES;
    62	}
    63	
    64	export function readProfile(storage?: ProfileStorage): LocalProfile {
    65	    const target = resolveStorage(storage);
    66	    let raw: string | null;
    67	    try { raw = target.getItem(PROFILE_STORAGE_KEY); }
    68	    catch { throw new ProfileStorageError('Your local profile could not be read. Check browser storage permissions.'); }
    69	    if (raw === null) return emptyProfile();
    70	    if (!withinSizeLimit(raw)) throw new ProfileStorageError('Your local profile is too large to load safely. Clear it to start again.');
    71	    try {
    72	        return profileSchema.parse(JSON.parse(raw));
    73	    } catch {
    74	        throw new ProfileStorageError('Your local profile contains unreadable data. It has been kept intact; clear it to start again.');
    75	    }
    76	}
    77	
    78	function writeProfile(profile: LocalProfile, storage: ProfileStorage): LocalProfile {
    79	    const raw = JSON.stringify(profile);
    80	    if (!withinSizeLimit(raw)) throw new ProfileStorageError('Your local profile is full. Delete an older conversation and try again.');
    81	    try { storage.setItem(PROFILE_STORAGE_KEY, raw); }
    82	    catch { throw new ProfileStorageError('This report could not be saved locally. Browser storage may be full or blocked.'); }
    83	    return profile;
    84	}
    85	
    86	export function saveSession(session: SavedSession, storage?: ProfileStorage): LocalProfile {
    87	    const validated = sessionSchema.safeParse(session);
    88	    if (!validated.success) throw new ProfileStorageError('This report could not be saved because its session data is invalid.');
    89	    const target = resolveStorage(storage);
    90	    const profile = readProfile(target);
    91	    const sessions = [...profile.sessions.filter(saved => saved.id !== session.id), validated.data]
    92	        .sort((a, b) => Date.parse(a.completedAt) - Date.parse(b.completedAt))
    93	        .slice(-MAX_PROFILE_SESSIONS);
    94	    return writeProfile({ version: 1, sessions }, target);
    95	}
    96	
    97	export function deleteSession(id: string, storage?: ProfileStorage): LocalProfile {
    98	    const target = resolveStorage(storage);
    99	    const profile = readProfile(target);
   100	    return writeProfile({ version: 1, sessions: profile.sessions.filter(session => session.id !== id) }, target);
   101	}
   102	
   103	export function clearProfile(storage?: ProfileStorage): LocalProfile {
   104	    const target = resolveStorage(storage);
   105	    try { target.removeItem(PROFILE_STORAGE_KEY); }
   106	    catch { throw new ProfileStorageError('Your local profile could not be cleared. Check browser storage permissions.'); }
   107	    return emptyProfile();
   108	}
   109	
   110	const normalizeScenario = (value?: string) => value?.trim().toLocaleLowerCase('en').replace(/\s+/g, ' ') ?? '';
   111	export function getComparableSessions(current: SavedSession, sessions: SavedSession[]): SavedSession[] {
   112	    return sessions.filter(session => session.id !== current.id
   113	        && Date.parse(session.completedAt) <= Date.parse(current.completedAt)
   114	        && session.scenarioId === current.scenarioId && session.difficulty === current.difficulty
   115	        && normalizeScenario(session.targetRole) === normalizeScenario(current.targetRole)
   116	        && (current.scenarioId !== 'custom' || normalizeScenario(session.customScenario) === normalizeScenario(current.customScenario)))
   117	        .sort((a, b) => Date.parse(a.completedAt) - Date.parse(b.completedAt));
   118	}
   119	
   120	export type ScoreChange = { current: number; previous: number; delta: number };
   121	export type SessionComparison = {
   122	    previousSessionId: string;
   123	    metrics: (ScoreChange & { key: typeof COACHING_METRICS[number]['key']; label: string })[];
   124	    overall: ScoreChange;
   125	};
   126	export function compareSession(current: SavedSession, sessions: SavedSession[]): SessionComparison | null {
   127	    const previous = getComparableSessions(current, sessions).at(-1);
   128	    if (!current.report.assessment || !previous?.report.assessment) return null;
   129	    const currentAssessment = current.report.assessment;
   130	    const previousAssessment = previous.report.assessment;
   131	    const metrics = COACHING_METRICS.map(({ key, label }) => {
   132	        const current = currentAssessment[key].score;
   133	        const prior = previousAssessment[key].score;
   134	        return { key, label, current, previous: prior, delta: current - prior };
   135	    });
   136	    const currentAverage = metrics.reduce((total, item) => total + item.current, 0) / metrics.length;
   137	    const previousAverage = metrics.reduce((total, item) => total + item.previous, 0) / metrics.length;
   138	    return { previousSessionId: previous.id, metrics, overall: { current: currentAverage, previous: previousAverage, delta: currentAverage - previousAverage } };
   139	}

