     1	import { createSpeechTranscript } from './speech-transcript';
     2	/** Live words for manual recordings; recorded WAV remains the final transcript source. */
     3	export function createManualTranscript(callbacks: {
     4	  onTranscript: (text: string) => void;
     5	  onError: (message: string) => void;
     6	}) {
     7	  let generation = 0;
     8	  let active = false;
     9	  let ready = false;
    10	  let rate = 0;
    11	  const transcript = createSpeechTranscript();
    12	  let pending: Float32Array[] = [];
    13	  let pendingSamples = 0;
    14	  let frame = new Float32Array(0);
    15	  let frameOffset = 0;
    16	  let socket: WebSocket | null = null;
    17	  let request: AbortController | null = null;
    18	  let timer: ReturnType<typeof setTimeout> | null = null;
    19	
    20	  function stop() {
    21	    generation++; active = false; ready = false;
    22	    request?.abort(); request = null;
    23	    if (timer) clearTimeout(timer); timer = null;
    24	    if (socket) {
    25	      socket.onopen = null; socket.onmessage = null;
    26	      socket.onerror = null; socket.onclose = null; socket.close();
    27	    }
    28	    socket = null; pending = []; pendingSamples = 0; transcript.reset();
    29	    frame = new Float32Array(0); frameOffset = 0;
    30	  }
    31	  function fail() {
    32	    if (!active) return;
    33	    stop();
    34	    callbacks.onError("Live transcription unavailable. Finish your recording to transcribe your answer.");
    35	  }
    36	  function send(message: object) {
    37	    if (!socket || socket.readyState !== 1) return false;
    38	    if (socket.bufferedAmount > 256 * 1024) { fail(); return false; }
    39	    try { socket.send(JSON.stringify(message)); return true; }
    40	    catch { fail(); return false; }
    41	  }
    42	  function sendFrame(samples: Float32Array) {
    43	    const bytes = new Uint8Array(samples.length * 2);
    44	    const view = new DataView(bytes.buffer);
    45	    for (let i = 0; i < samples.length; i++) {
    46	      const value = Math.max(-1, Math.min(1, samples[i]));
    47	      view.setInt16(i * 2, Math.round(value * (value < 0 ? 32768 : 32767)), true);
    48	    }
    49	    let binary = "";
    50	    for (const byte of bytes) binary += String.fromCharCode(byte);
    51	    send({ type: "audio", audio: btoa(binary) });
    52	  }
    53	  function push(samples: Float32Array) {
    54	    if (!active) return;
    55	    // Bounded startup buffer preserves words spoken while connecting.
    56	    if (!ready && pendingSamples + frameOffset + samples.length > rate * 10) { fail(); return; }
    57	    let offset = 0;
    58	    while (offset < samples.length && active) {
    59	      const count = Math.min(frame.length - frameOffset, samples.length - offset);
    60	      frame.set(samples.subarray(offset, offset + count), frameOffset);
    61	      frameOffset += count; offset += count;
    62	      if (frameOffset !== frame.length) continue;
    63	      const complete = frame;
    64	      frame = new Float32Array(Math.round(rate * 0.08)); frameOffset = 0;
    65	      if (ready) sendFrame(complete);
    66	      else { pending = [...pending, complete]; pendingSamples += complete.length; }
    67	    }
    68	  }
    69	  function onMessage(data: string) {
    70	    let message: Record<string, unknown>;
    71	    try {
    72	      message = JSON.parse(data);
    73	      if (!message || typeof message !== "object") throw new Error();
    74	    } catch { fail(); return; }
    75	    if (message.type === "ready" && !ready) {
    76	      ready = true;
    77	      if (timer) clearTimeout(timer); timer = null;
    78	      const queued = pending; pending = []; pendingSamples = 0;
    79	      for (const frame of queued) { if (!active) break; sendFrame(frame); }
    80	    } else if (message.type === "text" && typeof message.text === "string") {
    81	      try { transcript.add(message); } catch { fail(); return; }
    82	      callbacks.onTranscript(transcript.text());
    83	    } else if (message.type === "end_text") {
    84	      transcript.add(message);
    85	    } else if (message.type === "error" || message.type === "end_of_stream") fail();
    86	  }
