    64	export function readProfile(storage?: ProfileStorage): LocalProfile {
    65	    const target = resolveStorage(storage);
    66	    let raw: string | null;
    67	    try { raw = target.getItem(PROFILE_STORAGE_KEY); }
    68	    catch { throw new ProfileStorageError('Your local profile could not be read. Check browser storage permissions.'); }
    69	    if (raw === null) return emptyProfile();
    70	    if (!withinSizeLimit(raw)) throw new ProfileStorageError('Your local profile is too large to load safely. Clear it to start again.');
    71	    try {
    72	        return profileSchema.parse(JSON.parse(raw));
    73	    } catch {
