    27	    let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
    28	    let rejectAbort!: (reason: ApiError) => void;
    29	    const aborted = new Promise<never>((_resolve, reject) => { rejectAbort = reject; });
    30	    const abort = () => {
    31	        controller.abort();
    32	        rejectAbort(failed());
    33	        void reader?.cancel().catch(() => undefined);
    34	    };
    35	    request.signal.addEventListener('abort', abort, { once: true });
    36	    const timer = setTimeout(abort, 10000);
    37	    const consume = async () => {
    38	        if (request.signal.aborted) throw failed();
    39	        const response = await fetch('https://api.gradium.ai/api/api-keys/token', {
    40	            method: 'GET', headers: { 'x-api-key': key }, signal: controller.signal
    41	        });
    42	        if (controller.signal.aborted || !response.ok || !response.body || Number(response.headers.get('content-length')) > 65536) {
    43	            void response.body?.cancel().catch(() => undefined);
    44	            throw failed();
    45	        }
    46	        reader = response.body.getReader();
    47	        const chunks: Uint8Array[] = [];
    48	        let length = 0;
    49	        while (true) {
    50	            const chunk = await reader.read();
    51	            if (chunk.done) break;
    52	            length += chunk.value.byteLength;
    53	            if (length > 65536) { await reader.cancel(); throw failed(); }
    54	            chunks.push(chunk.value);
    55	        }
    56	        const bytes = new Uint8Array(length);
    57	        let offset = 0;
